import assert from 'node:assert/strict';
import { statSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

// Experiment-only interception; no runtime source, pragma settings or SQL changes.
export async function observeWal(root, variant, onBoundary = () => {}) {
  assert.ok(['baseline', 'candidate'].includes(variant));
  const { default: Database } = await import(pathToFileURL(join(root, 'apps/api/node_modules/better-sqlite3/lib/index.js')));
  const { measureSync } = await import(pathToFileURL(join(root, 'apps/api/src/measurements.ts')));
  const pragma = Database.prototype.pragma, close = Database.prototype.close;
  const targets = new Set(), checkpoints = [], closes = [], configurations = [];
  const thresholdBytes = 8 * 1024 ** 2;
  const sizes = db => Object.fromEntries(['', '-wal', '-shm'].map(suffix => {
    try { return [suffix || 'database', statSync(db.name + suffix).size]; }
    catch (error) { if (error.code === 'ENOENT') return [suffix || 'database', 0]; throw error; }
  }));
  function checkpoint(db, mode, reason) {
    assert.equal(db.inTransaction, false);
    const before = sizes(db), started = performance.now();
    const result = pragma.call(db, `wal_checkpoint(${mode})`);
    const nativeMs = performance.now() - started;
    checkpoints.push({ ordinal: checkpoints.length + 1, mode, reason, nativeMs, before, after: sizes(db), result });
    assert.equal(result.length, 1);
    assert.equal(result[0].busy, 0);
    assert.equal(result[0].log, result[0].checkpointed, 'Incomplete checkpoint in isolated producer');
    return result;
  }
  Database.prototype.pragma = function (sql, options) {
    if (sql !== 'wal_checkpoint(TRUNCATE)' || !this.name.replaceAll('\\', '/').endsWith('/.work/database.sqlite'))
      return pragma.call(this, sql, options);
    if (!targets.has(this)) {
      targets.add(this);
      const configuration = {
        journalMode: pragma.call(this, 'journal_mode', { simple: true }),
        synchronous: pragma.call(this, 'synchronous', { simple: true }),
        pageSize: pragma.call(this, 'page_size', { simple: true }),
        autoCheckpointPages: pragma.call(this, 'wal_autocheckpoint', { simple: true }),
        sqlite: this.prepare('SELECT sqlite_version() AS version').get().version,
      };
      configurations.push(configuration);
      assert.equal(configuration.journalMode, 'wal');
      assert.equal(configuration.synchronous, 1, 'Stop if the actual Store configuration changes');
      assert.equal(configuration.autoCheckpointPages, 1000);
    }
    onBoundary('before', this, checkpoints);
    const threshold = sizes(this)['-wal'] >= thresholdBytes;
    const mode = variant === 'baseline' || threshold ? 'TRUNCATE' : 'PASSIVE';
    const result = checkpoint(this, mode, variant === 'baseline' ? 'per-slot' : threshold ? 'threshold' : 'per-slot');
    onBoundary('after', this, checkpoints);
    return result;
  };
  Database.prototype.close = function () {
    if (!targets.has(this)) return close.call(this);
    if (variant === 'candidate') measureSync('db.walCheckpoint.final', () => checkpoint(this, 'TRUNCATE', 'final'));
    const before = sizes(this), started = performance.now();
    const result = close.call(this);
    closes.push({ before, after: sizes(this), elapsedMs: performance.now() - started });
    return result;
  };
  return {
    report: () => ({ variant, thresholdBytes, configurations, checkpoints, closes }),
    restore: () => { Database.prototype.pragma = pragma; Database.prototype.close = close; },
  };
}

