import { readFile, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import assert from 'node:assert/strict';
import { observeWal } from './l5-wal-policy.mjs';
const [root, output, variant] = process.argv.slice(2);
const policy = await observeWal(root, variant);
try {
  // Reuse the exact producer pilot used for #216/#218, including its fixed inputs,
  // real runLeaguePartition, clean SHA checks, Measurements and output verification.
  await import('./l5-queue-pilot.mjs');
  const result = JSON.parse(await readFile(output, 'utf8'));
  result.walPolicy = policy.report();
  result.observerSha256 = {};
  for (const file of ['l5-wal-pilot.mjs', 'l5-wal-policy.mjs'])
    result.observerSha256[file] = createHash('sha256').update(await readFile(new URL(file, import.meta.url))).digest('hex');
  await writeFile(output, JSON.stringify(result, null, 2) + '\n');
  assert.equal(result.walPolicy.checkpoints.filter(c => c.reason !== 'final').length, 10);
  assert.equal(result.walPolicy.configurations.length, 1);
} finally { policy.restore(); }

