import assert from 'node:assert/strict';
import { execFileSync, spawnSync } from 'node:child_process';
import { mkdtempSync, readFileSync, writeFileSync, existsSync, rmSync, readdirSync, statSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { pathToFileURL, fileURLToPath } from 'node:url';
import { createHash } from 'node:crypto';
import { observeWal } from './l5-wal-policy.mjs';
const [root, output, action = 'parent', variant, point, target] = process.argv.slice(2);
const moduleAt = path => import(pathToFileURL(join(root, path)));
const [{ batchInput }, { createBatchPlan }, { runBatch }, { openStore }] = await Promise.all([
  moduleAt('apps/api/test-support/batches.ts'), moduleAt('apps/api/src/batch/batch-plan.ts'),
  moduleAt('apps/api/src/batch/batch-runner.ts'), moduleAt('apps/api/src/db/store.ts'),
]);
const source = { sha: execFileSync('git', ['rev-parse', 'HEAD'], { cwd: root, encoding: 'utf8' }).trim(), node: process.versions.node, platform: process.platform, arch: process.arch };
assert.equal(execFileSync('git', ['status', '--porcelain'], { cwd: root, encoding: 'utf8' }).trim(), '');
function databaseRows(db) {
  return {
    results: db.prepare('SELECT simulation_hash, result_hash, replay_id FROM battle_results ORDER BY simulation_hash').all(),
    jobs: db.prepare('SELECT simulation_hash, state, attempts FROM simulation_jobs ORDER BY simulation_hash').all(),
    attempts: db.prepare('SELECT job_id, number, state FROM simulation_attempts ORDER BY job_id, number').all(),
  };
}
if (action === 'child') {
  const plan = await createBatchPlan(await batchInput(3), source);
  const policy = await observeWal(root, variant, (boundary, db, checkpoints) => {
    const ordinal = checkpoints.length + (boundary === 'before' ? 1 : 0);
    if (boundary !== point || ordinal !== 3) return;
    writeFileSync(output, JSON.stringify({ source, rows: databaseRows(db), policy: policy.report(), walBytes: statSync(db.name + '-wal').size, indexFiles: existsSync(join(target, 'indexes')) ? readdirSync(join(target, 'indexes')) : [] }, null, 2) + '\n');
    // Deliberately skip runtime/database close and all finally blocks.
    process.exit(83);
  });
  try { await runBatch(plan, target, source, { workers: 1 }); }
  finally { policy.restore(); }
  throw Error('Crash boundary was not reached');
}
const records = [], startedAt = new Date().toISOString();
for (const variant of ['baseline', 'candidate']) for (const point of ['before', 'after']) {
  const target = mkdtempSync(join(tmpdir(), 'l5-wal-crash-'));
  const childOutput = join(target, 'crash.json');
  const command = [process.execPath, '--import', join(root, 'apps/cli/node_modules/tsx/dist/loader.mjs'), fileURLToPath(import.meta.url), root, childOutput, 'child', variant, point, target];
  try {
    const child = spawnSync(command[0], command.slice(1), { cwd: root, encoding: 'utf8', timeout: 30000, maxBuffer: 65536 });
    assert.equal(child.status, 83, child.stderr);
    const crashed = JSON.parse(readFileSync(childOutput, 'utf8'));
    assert.equal(crashed.rows.results.length, 3);
    assert.deepEqual(crashed.indexFiles, []);
    const filename = join(target, '.work/database.sqlite');
    const reopened = openStore(filename);
    const integrity = reopened.db.pragma('quick_check');
    assert.deepEqual(integrity, [{ quick_check: 'ok' }]);
    assert.deepEqual(databaseRows(reopened.db), crashed.rows);
    reopened.close();
    const plan = await createBatchPlan(await batchInput(3), source);
    const resumed = await runBatch(plan, target, source, { workers: 1 });
    assert.equal(resumed.index.complete, true);
    assert.equal(resumed.index.slots.length, 3);
    assert.ok(resumed.index.slots.every(slot => slot.reused && slot.state === 'complete' && slot.receipt));
    const final = openStore(filename), rows = databaseRows(final.db);
    assert.deepEqual(rows, crashed.rows);
    final.close();
    assert.equal(readdirSync(target).filter(name => name.startsWith('.bundle-staging-')).length, 0);
    records.push({ variant, point, command, childExit: child.status, stdout: child.stdout, stderr: child.stderr, crashed, integrity, resumed: { complete: resumed.index.complete, reused: 3, additionalAttempts: 0, rowsUnchanged: true, slots: resumed.index.slots.map(slot => ({ slot: slot.slotId, simulation: slot.simulationHash, resultHash: slot.receipt.resultHash })) } });
  } finally { rmSync(target, { recursive: true, force: true }); }
}
// Exercise the threshold branch with owned synthetic metadata, outside timed trials.
const probeRoot = mkdtempSync(join(tmpdir(), 'l5-wal-threshold-'));
let threshold;
try {
  const policy = await observeWal(root, 'candidate');
  const store = openStore(join(probeRoot, '.work/database.sqlite'));
  try {
    store.db.exec('CREATE TABLE wal_probe(payload BLOB NOT NULL) STRICT');
    store.db.prepare('INSERT INTO wal_probe(payload) VALUES (zeroblob(?))').run(9 * 1024 ** 2);
    store.db.pragma('wal_checkpoint(TRUNCATE)');
    threshold = policy.report();
    assert.equal(threshold.checkpoints[0].reason, 'threshold');
    assert.equal(threshold.checkpoints[0].mode, 'TRUNCATE');
    assert.equal(threshold.checkpoints[0].after['-wal'], 0);
  } finally { store.close(); policy.restore(); }
} finally { rmSync(probeRoot, { recursive: true, force: true }); }
writeFileSync(output, JSON.stringify({ startedAt, finishedAt: new Date().toISOString(), source, driverSha256: createHash('sha256').update(readFileSync(fileURLToPath(import.meta.url))).digest('hex'), note: 'Three existing 30-step batch fixtures; application-process abrupt exit only, not power-loss/system-crash simulation. This is not performance evidence. No expected outputs changed. Threshold probe uses synthetic 9MiB metadata outside timed trials.', records, threshold }, null, 2) + '\n');
console.log(JSON.stringify({ crashCases: records.length, allRecovered: records.every(r => r.resumed.rowsUnchanged), thresholdTriggered: threshold.checkpoints[0].reason }));
